function caliKey(group,i){return group[0]+'_'+i}
function caliDone(group,i){return (S.caliMastery[caliKey(group,i)]||0)>=5}
function caliUnlocked(group,i){return i===0||caliDone(group,i-1)}
function caliGate(group,i){let v=group[3][i][0];let gates={'Wall Push-up':'10 reps نظيفة','Push-up':'10 reps نظيفة','Pull-up':'5 reps نظيفة','L-sit':'15 ثانية','Freestanding Handstand':'20 ثانية','Handstand Push-up':'3 reps نظيفة','Tuck Planche':'10 ثوانٍ','Advanced Tuck Planche':'8 ثوانٍ','Front Lever':'8 ثوانٍ','Back Lever Progression':'10 ثوانٍ','Human Flag':'5 ثوانٍ','Muscle-up':'3 reps نظيفة','Pistol Squat':'5/رجل'};return gates[v]||'5 حصص بجودة عالية'}
function caliView(){
 let total=CALI.reduce((a,g)=>a+g[3].length,0),done=CALI.reduce((a,g)=>a+g[3].filter((_,i)=>caliDone(g,i)).length,0);
 document.getElementById('view').innerHTML=`<section class="card"><div class="eyebrow">بناء جسم + مهارات</div><h2>🤸 الكالستنكس التطوري</h2><p class="muted">مو مجرد تمارين تكرار: كل حركة لها إتقان تدريجي. عند إكمالها 5 حصص تقنية تُفتح الحركة التالية تلقائياً، ومع كل مستوى تصبح المهارة أصعب.</p><div class="xp"><i style="width:${Math.round(done/total*100)}%"></i></div><div class="row"><span>المهارات المكتملة</span><b>${done} / ${total}</b></div></section>
 <section class="grid2 section">${CALI.map(g=>`<div class="card"><h3>${g[1]}</h3><p class="muted">${g[2]}</p>${g[3].map((v,i)=>{let n=S.caliMastery[caliKey(g,i)]||0,u=caliUnlocked(g,i),d=caliDone(g,i);return `<div class="skill ${!u?'locked':''}"><div class="row"><b>${i+1}. ${v[0]}</b><span class="tag">${d?'✓ مكتملة':u?'مفتوحة':'🔒 مقفلة'}</span></div><p class="muted">${v[1]}</p><div class="bar"><i style="width:${Math.min(100,n/5*100)}%"></i></div><small>${n}/5 حصص إتقان • معيار: ${escapeHtml(caliGate(g,i))}</small>${u&&!d?`<button class="btn blue" style="margin-top:8px" onclick="trainCali('${g[0]}',${i})">تدريب + إتقان</button>`:''}</div>`}).join('')}</div>`).join('')}</section>`;
}
function trainCali(gid,i){let g=CALI.find(x=>x[0]===gid);if(!g||!caliUnlocked(g,i)||caliDone(g,i))return;let x=g[3][i];startTrainingChallenge({sport:'🤸 الكالستنكس',title:'🤸 '+x[0],exercise:x[0],desc:x[1]+' نفّذ الحركة ضمن قدرتك وتوقف عند الألم.',work:x[0].toLowerCase().includes('hold')?20:30,rest:15,rounds:3,mode:'cali',group:g,index:i})}
function showCali(id,i){let g=CALI.find(a=>a[0]===id),v=g[3][i];showModal(`<h2>🤸 ${escapeHtml(v[0])}</h2><p>${escapeHtml(v[1])}</p><div class="card"><h3>🎯 معيار الإتقان</h3><p><b>${escapeHtml(caliGate(g,i))}</b> بدون تدهور واضح في الشكل، مع تحكم بالتنفس والحركة.</p><h3>التدرج</h3><p>لا تنتقل للحركة التالية إلا عندما تتحكم بالحالية. إذا كان الشكل سيئاً أو ظهر ألم، ارجع لدرجة أسهل.</p><ul><li>ابدأ بإحماء الكتفين والرسغين والمفاصل.</li><li>الجودة والتحكم أهم من عدد التكرارات.</li><li>المهارات المتقدمة مثل Handstand وPlanche وLever وHuman Flag تحتاج تدرجات طويلة، وليست قفزة واحدة.</li><li>إذا ظهر ألم حاد أو غير معتاد، أوقف الحركة ولا تحاول تجاوز الألم.</li></ul></div><a class="btn primary" target="_blank" rel="noopener" href="https://www.youtube.com/results?search_query=${encodeURIComponent(v[0]+' calisthenics tutorial progression')}">▶️ شرح وتدرج فيديو</a>`)}
function fitnessView(){let r=readinessScore();document.getElementById('view').innerHTML=`<section class="card"><div class="eyebrow">قدرات اللاعب</div><h2>💪 القوة واللياقة الشاملة</h2><p class="muted">قوة نسبية + انفجار + تحمل هوائي ولاهوائي + كور + قبضة + حركة + توازن + Prehab.</p><div class="grid2"><div class="card"><h3>🏋️ القوة</h3><p>Push/Pull • Squat • Split Squat • Hinge/Nordic • Core</p></div><div class="card"><h3>⚡ الانفجار</h3><p>قفز • ضغط انفجاري • تغيير اتجاه • هبوط مضبوط</p></div><div class="card"><h3>🫁 التحمل</h3><p>قاعدة هوائية + جولات لاهوائية حسب الجاهزية</p></div><div class="card"><h3>🛡️ Prehab</h3><p>كتف • رقبة • ركبة • كاحل • ورك • قبضة</p></div></div><button class="btn primary" onclick="advancedTesting()">📏 اختبار القدرات</button> <button class="btn blue" onclick="go('smart')">🧭 خطتي اليوم</button></section><section class="section card"><h3>جاهزية اليوم: ${r}/100</h3><div class="bar"><i style="width:${r}%"></i></div><p class="muted">القوة وحدها لا تصنع مقاتلاً كاملاً؛ التقنية، التحمل، اتخاذ القرار والتعافي تدخل كلها في التطور.</p></section>`}

const SPORT_CHALLENGES={
 'الملاكمة':[['🥊 الجاب','Jab','اضرب الجاب بسرعة مع رجوع اليد للحماية.',20,10,3],['🥊 الكروس','Cross','ثبّت الوقفة ولف الورك مع الكروس.',20,10,3],['🥊 تركيبات','1-2 Combo','جاب + كروس بتقنية نظيفة.',30,15,3]],
 'الكيك بوكسينغ':[['🦵 الركلة الأمامية','Front Kick','ركلة أمامية مع رجوع سريع للوقفة.',20,10,3],['🦵 Round Kick','Round Kick','دوران الورك والعودة للوقفة.',25,10,3],['🦵 كومبو يد + قدم','Boxing + Kick','تركيبة ضربات ثم ركلة.',30,15,3]],
 'مواي تاي':[['🇹🇭 Teep','Teep','تحكم بالتوازن وعودة الرجل بسرعة.',20,10,3],['🇹🇭 الركبة','Knee','ارفع الركبة بتحكم.',20,10,3],['🇹🇭 كلينش','Clinch','حركة قدم وكلينش تقني بدون قوة زائدة.',30,15,3]],
 'المصارعة':[['🤼 Level Change','Level Change','غيّر المستوى مع ظهر محايد وعودة للوقفة.',20,10,3],['🤼 Sprawl','Sprawl','دافع عن الإسقاط بحركة مسيطَر عليها.',20,15,3],['🤼 Single Leg','Single Leg','تدرّب على الدخول التقني بدون رمي أو ضغط مؤذٍ.',30,15,3]],
 'الجوجيتسو BJJ':[['🥋 Guard','Guard','حافظ على القاعدة والتنفس والسيطرة.',30,15,3],['🥋 Escape','Escape','تدرّب على الهروب التقني ببطء.',30,15,3],['🥋 Guard Pass','Guard Pass','انتقل من السيطرة إلى المرور بتحكم.',30,15,3]],
 'MMA':[['⚔️ إدارة المسافة','Distance','تحرك واضبط المسافة مع حراسة جيدة.',30,15,3],['⚔️ دخول الإسقاط','Takedown Entry','دخول تقني بدون تنفيذ خطر أو إسقاط شريك.',30,15,3],['⚔️ Mix Striking + Grappling','MMA Flow','اربط الضرب بالحركة والجراپلينغ بشكل تقني.',40,20,3]],
 'الكالستنكس':[['🤸 Push-up','Push-up','تكرارات نظيفة مع جسم ثابت.',30,15,3],['🤸 Squat','Squat','نزول وصعود بتحكم كامل.',30,15,3],['🤸 Plank','Plank','ثبات الكور مع تنفس هادئ.',30,15,3]],
 'القوة':[['🏋️ Strength Circuit','Strength','حركة مقاومة آمنة حسب معداتك.',40,20,3]],
 'اللياقة':[['🫁 Conditioning','Conditioning','جهد متدرج بدون تجاوز الجاهزية.',40,20,4]],
 'الحركة والمرونة':[['🧘 Mobility Flow','Mobility','حركات مرونة وتحكم بدون ألم.',45,15,3]],
 'التعافي':[['🫀 Recovery Flow','Recovery','تنفس وحركة خفيفة واستعادة.',60,15,2]]
};
let activeTraining=null,trainingTimer=null;
function training(){document.getElementById('view').innerHTML=`<section class="card exerciseHero"><div class="eyebrow">جلسة تدريب تفاعلية</div><h2>🥊 اختار الرياضة والتحدي</h2><p class="muted">اختار التمرين، ابدأ المؤقت، نفّذ الجولة، وخلي التطبيق يحسب الجولات والـXP والتقدم تلقائياً.</p><div class="grid2"><div class="field"><label>الرياضة</label><select id="lt" onchange="refreshTrainingChallenges()">${Object.keys(SPORT_CHALLENGES).map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>التحدي</label><select id="lc" onchange="updateTrainingPreview()"></select></div></div><div class="grid3"><div class="scorebox"><small>الجولات</small><div class="trainingStat" id="previewRounds">3</div></div><div class="scorebox"><small>عمل</small><div class="trainingStat" id="previewWork">20s</div></div><div class="scorebox"><small>راحة</small><div class="trainingStat" id="previewRest">10s</div></div></div><button class="btn primary" style="margin-top:12px;width:100%" onclick="startSelectedTraining()">🥊 ابدأ التمرين</button><button class="btn gold" style="margin-top:8px;width:100%" onclick="quickChallenge()">⚡ تحدي سريع لأضعف نقطة</button></section><section class="section card"><h3>🧠 كيف تمشي الجلسة؟</h3><p class="muted">تجهيز 5 ثوانٍ → جولة عمل → راحة → الجولة التالية → اكتمال التحدي. كل جولة مكتملة تُحفظ فوراً، وإذا أوقفت الجلسة لا تضيع الجولات السابقة.</p></section>`;refreshTrainingChallenges()}
function refreshTrainingChallenges(){let sport=document.getElementById('lt')?.value,sel=document.getElementById('lc');if(!sel)return;let arr=SPORT_CHALLENGES[sport]||[];sel.innerHTML=arr.map((x,i)=>`<option value="${i}">${x[0]} — ${x[2]}</option>`).join('');updateTrainingPreview()}
function updateTrainingPreview(){let sport=document.getElementById('lt')?.value,i=+(document.getElementById('lc')?.value||0),x=(SPORT_CHALLENGES[sport]||[])[i];if(!x)return;document.getElementById('previewRounds').textContent=x[5];document.getElementById('previewWork').textContent=x[3]+'s';document.getElementById('previewRest').textContent=x[4]+'s'}
function startSelectedTraining(){let sport=document.getElementById('lt')?.value,i=+(document.getElementById('lc')?.value||0),x=(SPORT_CHALLENGES[sport]||[])[i];if(!x)return;startTrainingChallenge({sport,title:x[0],exercise:x[1],desc:x[2],work:x[3],rest:x[4],rounds:x[5],mode:'sport'})}
function startTrainingChallenge(cfg){if(trainingTimer)clearInterval(trainingTimer);activeTraining={...cfg,phase:'ready',remaining:5,roundsDone:0,xp:0,startedAt:Date.now()};renderTrainingModal();trainingTimer=setInterval(tickTraining,1000)}
function tickTraining(){if(!activeTraining)return;activeTraining.remaining--;if(activeTraining.remaining>0){renderTrainingModal();return}if(activeTraining.phase==='ready'){activeTraining.phase='work';activeTraining.remaining=activeTraining.work;renderTrainingModal();return}if(activeTraining.phase==='work'){activeTraining.roundsDone++;activeTraining.xp+=20;addXP(20);S.history.push({date:today(),type:'training_round',name:activeTraining.sport+' • '+activeTraining.exercise+' • الجولة '+activeTraining.roundsDone,xp:20,round:activeTraining.roundsDone});save();if(activeTraining.roundsDone>=activeTraining.rounds){finishTrainingChallenge();return}activeTraining.phase='rest';activeTraining.remaining=activeTraining.rest;renderTrainingModal();return}if(activeTraining.phase==='rest'){activeTraining.phase='work';activeTraining.remaining=activeTraining.work;renderTrainingModal()}}
function renderTrainingModal(){if(!activeTraining)return;let a=activeTraining,phase=a.phase==='ready'?'استعد':a.phase==='work'?'🔥 نفّذ الجولة':'😮‍💨 استراحة';let dots=Array.from({length:a.rounds},(_,i)=>`<span class="roundDot ${i<a.roundsDone?'done':i===a.roundsDone&&a.phase==='work'?'active':''}"></span>`).join('');let sub=a.phase==='ready'?'خذ وضعية البداية':a.phase==='work'?a.desc:'تنفس واستعد للجولة التالية';showModal(`<div class="eyebrow">${escapeHtml(a.sport)}</div><h2>${escapeHtml(a.title)}</h2><p class="muted">${escapeHtml(sub)}</p><div class="roundDots">${dots}</div><div class="timerRing"><div><div class="trainingTimer">${a.remaining}</div><div class="muted">${phase}</div></div></div><div class="grid3"><div class="scorebox"><small>الجولة</small><div class="trainingStat">${Math.min(a.roundsDone+1,a.rounds)}/${a.rounds}</div></div><div class="scorebox"><small>XP الجولات</small><div class="trainingStat">+${a.xp}</div></div><div class="scorebox"><small>الحالة</small><div class="trainingStat" style="font-size:18px">${phase}</div></div></div><button class="btn danger" style="margin-top:12px;width:100%" onclick="stopTrainingChallenge()">إيقاف الجلسة</button>`)}
function finishTrainingChallenge(){let a=activeTraining;if(trainingTimer){clearInterval(trainingTimer);trainingTimer=null}let bonus=60;addXP(bonus);S.history.push({date:today(),type:'training',name:a.sport+' • '+a.exercise,xp:bonus+a.xp,rounds:a.roundsDone,completed:true});if(a.mode==='tech'){let k=techniqueKey(a.group,a.index);S.techniqueMastery[k]=(S.techniqueMastery[k]||0)+1;if(S.techniqueMastery[k]>=5){addXP(120);S.history.push({date:today(),type:'skill_unlock',name:'إتقان '+a.exercise,xp:120})}if(Number.isInteger(a.smartIndex)){let p=ensureSmartPlan();if(!p.completed.includes(a.smartIndex))p.completed.push(a.smartIndex)}}else if(a.mode==='cali'){let k=caliKey(a.group,a.index);S.caliMastery[k]=(S.caliMastery[k]||0)+1;S.stats.strength=Math.min(100,S.stats.strength+.35);S.stats.mobility=Math.min(100,S.stats.mobility+.15);if(S.caliMastery[k]>=5){addXP(100);S.history.push({date:today(),type:'skill_unlock',name:'إتقان '+a.exercise,xp:100})}}else{S.stats[a.sport==='الملاكمة'?'boxing':a.sport==='الكيك بوكسينغ'?'kickboxing':a.sport==='مواي تاي'?'muaythai':a.sport==='المصارعة'?'wrestling':a.sport==='الجوجيتسو BJJ'?'bjj':a.sport==='MMA'?'mma':a.sport==='اللياقة'?'cardio':a.sport==='القوة'||a.sport==='الكالستنكس'?'strength':a.sport==='الحركة والمرونة'?'mobility':'discipline']=Math.min(100,(S.stats[a.sport==='الملاكمة'?'boxing':a.sport==='الكيك بوكسينغ'?'kickboxing':a.sport==='مواي تاي'?'muaythai':a.sport==='المصارعة'?'wrestling':a.sport==='الجوجيتسو BJJ'?'bjj':a.sport==='MMA'?'mma':a.sport==='اللياقة'?'cardio':a.sport==='القوة'||a.sport==='الكالستنكس'?'strength':a.sport==='الحركة والمرونة'?'mobility':'discipline']||5)+.5)}gameReward('challenge',a.xp+bonus);if(S.lastDate!==today()){S.streak++;S.lastDate=today()}checkAch();save();let total=a.xp+bonus;activeTraining=null;showModal(`<h2>🏆 التحدي مكتمل!</h2><p>${escapeHtml(a.title)}</p><div class="grid2"><div class="scorebox"><small>الجولات المكتملة</small><div class="big">${a.roundsDone}/${a.rounds}</div></div><div class="scorebox"><small>المكافأة</small><div class="big">+${total} XP</div></div></div><p class="success">✓ تم حفظ الجولات والتقدم والـXP.</p><button class="btn primary" onclick="closeModal();render()">متابعة</button>`)}
function stopTrainingChallenge(){if(trainingTimer)clearInterval(trainingTimer);trainingTimer=null;let a=activeTraining;activeTraining=null;if(a){save();toast('تم حفظ الجولات المكتملة فقط')}closeModal();render()}

function logSession(){let دقيقة=+document.getElementById('lm').value||0,type=document.getElementById('lt').value,note=document.getElementById('ln').value,xp=Math.min(220,30+Math.round(دقيقة*1.4));addXP(xp);let map={'الملاكمة':'boxing','الكيك بوكسينغ':'kickboxing','مواي تاي':'muaythai','المصارعة':'wrestling','الجوجيتسو BJJ':'bjj','MMA':'mma','الكالستنكس':'strength','القوة':'strength','اللياقة':'cardio','الحركة والمرونة':'mobility','التعافي':'discipline'};S.stats[map[type]]=Math.min(100,S.stats[map[type]]+.7);S.history.push({date:today(),type:'session',name:type,xp,دقيقة,note});save();render();toast('تم التسجيل +'+xp+' خبرة')}
function quickChallenge(){let w=Object.entries(S.stats).sort((a,b)=>a[1]-b[1])[0];showModal(`<h2>⚡ تحدي سريع</h2><p>ركز على أضعف المهارة عندك: <b>${labels[w[0]]}</b></p><p>20 دقيقة تقنية مركزة + 5 دقائق تهدئة.</p><button class="btn primary" onclick="addXP(100);S.history.push({date:today(),type:'challenge',name:'سريع '+labels[w[0]],xp:100});save();closeModal();render()">إكمال +100 خبرة</button>`)}
const SPORT_SKILLS={
 '🥊 الملاكمة':[['stance','الوقفة والحركة'],['jab','الجاب'],['cross','الكروس'],['hook','الهوك'],['uppercut','الأبركت'],['slip','المراوغة'],['roll','الرول'],['parry','الصد'],['combos','التركيبات'],['angles','الزوايا'],['counter','الهجمات المرتدة']],
 '🦵 الكيك بوكسينغ':[['kick','ركلة أمامية'],['round','Round Kick'],['teep','Teep'],['check','صد الركلات'],['knee','ركبة أساسية'],['combokick','تركيبات اليد والقدم'],['switch','Switch Kick'],['lowkick','Low Kick'],['highkick','High Kick']],
 '🇹🇭 مواي تاي':[['stance','وقفة مواي تاي'],['teep','Teep'],['round','Round Kick'],['elbow','الكوع'],['knee','الركبة'],['clinch','كلينش'],['check','Check'],['lowkick','Low Kick'],['elbowcombo','تركيبات الكوع'],['clinchknee','ركب من الكلينش']],
 '🤼 المصارعة':[['stance','Wrestling Stance'],['level','Level Change'],['sprawl','Sprawl'],['single','Single Leg'],['double','Double Leg'],['defense','دفاع الإسقاط'],['scramble','Scramble'],['wall','المصارعة على الحائط'],['chain','ربط الإسقاطات']],
 '🥋 الجوجيتسو BJJ':[['base','Base'],['guard','Guard'],['mount','Mount'],['side','Side Control'],['escape','Escapes'],['sweep','Sweeps'],['pass','Guard Passing'],['back','Back Control'],['submission','Submissions'],['transition','Transitions']],
 '⚔️ MMA':[['stance','MMA Stance'],['distance','إدارة المسافة'],['entry','الدخول للإسقاط'],['cage','Cage Work'],['ground','Ground & Pound تقني'],['wallescape','الهروب من الحائط'],['scramble','Scramble'],['mix','Mixing Striking + Grappling'],['strategy','استراتيجية الجولة']]
};
function techniqueKey(group,i){return group+'_'+i}
function techniqueDone(group,i){return (S.techniqueMastery[techniqueKey(group,i)]||0)>=5}
function techniqueUnlocked(group,i){return i===0||techniqueDone(group,i-1)}
function skills(){
 let groups=Object.entries(SPORT_SKILLS);
 document.getElementById('view').innerHTML=`<section class="card"><div class="eyebrow">شجرة مهارات متعددة الرياضات</div><h2>🌳 MMA Skill Tree</h2><p class="muted">الملاكمة • الكيك بوكسينغ • مواي تاي • المصارعة • BJJ • MMA. كل مهارة تحتاج 5 حصص إتقان، وبعد إكمالها تُفتح المهارة التالية تلقائياً.</p>${groups.map(([g,arr])=>`<div class="section"><h2>${g}</h2><div class="tree">${arr.map((x,i)=>{let n=S.techniqueMastery[techniqueKey(g,i)]||0,d=techniqueDone(g,i),u=techniqueUnlocked(g,i);return `<div class="skill ${!u?'locked':''}"><div class="row"><b>${i+1}. ${x[1]}</b><span class="tag">${d?'✓ إتقان':u?'مفتوحة':'🔒'}</span></div><div class="bar"><i style="width:${Math.min(100,n/5*100)}%"></i></div><small>${n}/5 حصص</small>${u&&!d?`<button class="btn" style="margin-top:7px" onclick="trainTechnique('${escapeHtml(g)}',${i})">🥊 ابدأ التحدي</button>`:''}</div>`}).join('')}</div></div>`).join('')}</section>`;
}
function trainTechnique(group,i){let arr=SPORT_SKILLS[group];if(!arr||!techniqueUnlocked(group,i)||techniqueDone(group,i))return;let x=arr[i];startTrainingChallenge({sport:group,title:'🥋 '+x[1],exercise:x[1],desc:'نفّذ '+x[1]+' بتقنية نظيفة وتحكم. '+(x[0]==='takedown'?'لا تنفذ إسقاطاً على شريك بدون إشراف.':''),work:30,rest:15,rounds:3,mode:'tech',group,index:i})}
function stats(){let rows=Object.entries(S.stats).map(([k,v])=>`<tr><td>${labels[k]}</td><td>${Math.round(v)}</td><td><div class="bar"><i style="width:${v}%"></i></div></td></tr>`).join('');let total=S.history.reduce((a,x)=>a+(x.xp||0),0);document.getElementById('view').innerHTML=`<section class="grid3"><div class="card"><div class="big">${S.level}</div><small class="muted">المستوى</small></div><div class="card"><div class="big">${total}</div><small class="muted">إجمالي الخبرة</small></div><div class="card"><div class="big">${S.history.length}</div><small class="muted">السجلات</small></div></section><section class="section card"><h2>📊 مقاتل التحليلات</h2><table class="table"><tr><th>المهارة</th><th>النتيجة</th><th>التقدم</th></tr>${rows}</table></section><section class="section grid2"><div class="card"><h2>🏆 الإنجازات</h2>${S.achievements.map(x=>`<span class="tag">🏆 ${x}</span>`).join(' ')||'<div class="empty">ابدأ لتفتح الإنجازات.</div>'}</div><div class="card"><h2>🧬 مقاتل DNA</h2><p><b>الأسلوب:</b> ${S.dna.style||'—'}</p><p><b>القوة:</b> ${S.dna.strength||'—'}</p><p><b>نقطة الضعف:</b> ${S.dna.weakness||'—'}</p><p><b>الأولوية:</b> ${S.dna.priority||'—'}</p></div></section>`}
function sparring(){document.getElementById('view').innerHTML=`<section class="card"><div class="eyebrow">سجل السبارينغ</div><h2>🥋 سجّل السبارينغ</h2><div class="grid3"><div class="field"><label>الجولات</label><input id="sr" type="number" value="3"></div><div class="field"><label>مدة الجولة</label><input id="sm" type="number" value="3"></div><div class="field"><label>شدة 1–10</label><input id="si" type="number" min="1" max="10" value="6"></div></div><div class="grid2"><div class="field"><label>شو نجح؟</label><textarea id="sw"></textarea></div><div class="field"><label>شو فشل؟</label><textarea id="sf"></textarea></div></div><div class="field"><label>ملاحظات المدرب</label><textarea id="sc"></textarea></div><button class="btn primary" onclick="saveSparring()">حفظ السبارينغ + تحليل نمط</button></section><section class="section card"><h2>🧠 اكتشاف الأنماط</h2>${sparringPatterns()}</section><section class="section card"><h2>السجل</h2>${S.sparring.slice(-8).reverse().map(x=>`<div style="padding:9px 0;border-bottom:1px solid var(--line)"><b>${x.rounds}×${x.دقيقة}دقيقة</b> • الشدة ${x.intensity}/10<br><span class="success">✓ ${x.good||'—'}</span><br><span class="dangerText">✕ ${x.bad||'—'}</span></div>`).join('')||'<div class="empty">ما في سجلات بعد.</div>'}</section>`}
function saveSparring(){S.sparring.push({date:today(),rounds:+sr.value||3,minutes:+sm.value||3,intensity:+si.value||6,good:sw.value,bad:sf.value,coach:sc.value});addXP(100);S.history.push({date:today(),type:'sparring',name:'السبارينغ Log',xp:100});save();render();toast('🥋 السبارينغ saved')}
function sparringPatterns(){if(!S.sparring.length)return '<div class="muted">بعد عدة سجلات رح يبدأ النظام يلتقط المشاكل المتكررة.</div>';let bad=S.sparring.map(x=>x.bad||'').join(' ').toLowerCase();let hints=[];if(/guard|حارس|ايد|يد/.test(bad))hints.push('استعادة الحراسة يظهر كنمط متكرر.');if(/cardio|نفس|تعب/.test(bad))hints.push('اللياقة/التعب يظهر كنمط متكرر.');if(/takedown|اسقاط|مصارع/.test(bad))hints.push('الدفاع ضد الإسقاط يحتاج أولوية.');return hints.length?hints.map(x=>`<p>⚠️ ${x}</p>`).join(''):'<p>حالياً ما ظهر نمط واضح؛ استمر بالتسجيل.</p>'}
function progress(){document.getElementById('view').innerHTML=`<section class="card"><div class="row"><div><div class="eyebrow">مختبر التطور</div><h2>🎥 خزنة التطور</h2><div class="muted">صور وفيديوهات للمقارنة. الملفات المحلية تبقى على هذا الجهاز.</div></div><button class="btn primary" onclick="document.getElementById('mi').click()">+ الوسائط</button></div><input id="mi" class="hidden" type="file" accept="image/*,video/*" multiple onchange="addMedia(this.files)"></section><section class="section card"><h2>📈 الخط الزمني</h2><div class="timeline">${S.history.slice(-12).reverse().map(x=>`<div><b>${x.name}</b><div class="muted">${x.date} • +${x.xp||0} خبرة</div></div>`).join('')||'<div class="empty">ابدأ التدريب.</div>'}</div></section><section class="section media">${S.media.map((m,i)=>`<div class="card">${m.type.startsWith('image')?`<img src="${m.url}">`:`<video src="${m.url}" controls></video>`}<small class="muted">${m.date}</small><button class="btn danger" onclick="delMedia(${i})">حذف</button></div>`).join('')||'<div class="card empty">أضف أول صورة أو فيديو.</div>'}</section><section class="section card"><h2>🔬 المقارنة</h2><p class="muted">اختَر فيديو/صور لاحقاً لإرسالها إلى مدرب الذكاء الاصطناعي. المقارنة البصرية المتقدمة تحتاج خادم الذكاء الاصطناعي.</p><button class="btn blue" onclick="go('ai')">فتح مدرب الذكاء الاصطناعي</button></section>`}
function addMedia(files){[...files].forEach(f=>{if(f.size>30e6)return toast('الحد 30MB');let r=new FileReader();r.onload=()=>{S.media.push({type:f.type,url:r.result,date:today(),name:f.name});save();render()};r.readAsDataURL(f)})}function delMedia(i){S.media.splice(i,1);save();render()}
function camp(){let c=S.camp;if(!c)document.getElementById('view').innerHTML=`<section class="card"><div class="eyebrow">محرك معسكر النزال</div><h2>🏕️ ابدأ معسكر</h2><div class="grid2"><div class="field"><label>أسابيع</label><input id="cw" type="number" value="8" min="2" max="12"></div><div class="field"><label>الهدف</label><select id="cg"><option>بناء أساس</option><option>تحضير تقني</option><option>رفع اللياقة</option><option>تحضير لنزال مع المدرب</option></select></div></div><button class="btn primary" onclick="startCamp()">ابدأ المعسكر</button></section>`;else document.getElementById('view').innerHTML=`<section class="card"><div class="eyebrow">${c.weeks} أسابيع المعسكر</div><h2>🏕️ الأسبوع ${c.week}/${c.weeks}</h2><div class="bar"><i style="width:${c.week/c.weeks*100}%"></i></div><div class="grid3 section"><div><b>الأساس</b><p class="muted">تقنية + حجم معتدل</p></div><div><b>المرحلة الخاصة</b><p class="muted">سيناريوهات قتال تحت إشراف المدرب</p></div><div><b>التخفيف قبل النزال</b><p class="muted">خفض الحمل قرب النزال</p></div></div><button class="btn primary" onclick="advanceCamp()">إنهاء الأسبوع +250 خبرة</button> <button class="btn danger" onclick="S.camp=null;save();render()">إنهاء المعسكر</button></section>`}
function startCamp(){S.camp={weeks:+cw.value||8,week:1,goal:cg.value};save();render()}function advanceCamp(){if(S.camp.week<S.camp.weeks)S.camp.week++;addXP(250);save();render();toast('🏕️ الأسبوع complete')}
function nutrition(){let n=S.nutrition.at(-1)||{};document.getElementById('view').innerHTML=`<section class="card"><div class="eyebrow">وقود المقاتل</div><h2>🍗 تغذية بسيطة</h2><div class="grid3"><div class="field"><label>الوزن بالكيلوغرام</label><input id="nw" type="number" value="${n.weight||56}"></div><div class="field"><label>الهدف</label><select id="ng"><option>زيادة الوزن</option><option>المحافظة</option><option>خفض الوزن</option></select></div><div class="field"><label>ميزانية اليوم $</label><input id="nb" type="number" value="${n.budget||5}"></div></div><button class="btn primary" onclick="saveFuel()">احسب خطة اليوم</button></section><section class="section grid3"><div class="card"><h2>البروتين</h2><div class="big" id="pr">${Math.round((n.weight||56)*1.7)} غرام</div><small class="muted">تقدير عام</small></div><div class="card"><h2>الماء</h2><div class="big" id="wa">${Math.round((n.weight||56)*35/1000*10)/10} لتر</div></div><div class="card"><h2>أطعمة اقتصادية</h2><p class="muted">بيض • لبن/زبادي • عدس • رز • تونة/دجاج حسب المتاح</p></div></section><section class="section card"><h2>🥗 قاعدة</h2><p class="muted">لا يوجد هنا خفض الوزن قاسٍ أو توصيات طبية. إذا كنت صغير الوزن أو عندك هدف وزن لمنافسة، خليه مع مدرب/مختص.</p></section>`}
function saveFuel(){S.nutrition.push({date:today(),weight:+nw.value||56,budget:+nb.value||5,goal:ng.value});save();render();toast('التغذية plan saved')}
function recovery(){let last=S.sleep.at(-1)||{};let active=S.injuries.filter(x=>!x.cleared);document.getElementById('view').innerHTML=`<section class="card"><div class="eyebrow">محرك التعافي</div><h2>🫀 حالة الجسم</h2><div class="grid3"><div class="field"><label>النوم بالساعات</label><input id="rh" type="number" step="0.1" value="${last.hours||7}"></div><div class="field"><label>الإجهاد 1–10</label><input id="rf" type="number" min="1" max="10" value="${last.fatigue||5}"></div><div class="field"><label>ألم عام 0–10</label><input id="rp" type="number" min="0" max="10" value="${last.pain||0}"></div></div><button class="btn primary" onclick="saveRecovery()">تحديث التعافي</button></section><section class="section card"><h2>التوصية</h2><div class="big">${recoveryScore()} / 100</div><p>${recoveryAdvice()}</p></section><section class="section card"><h2>🩹 الإصابات</h2>${active.map((x,i)=>`<div class="row" style="padding:8px 0;border-bottom:1px solid var(--line)"><span>${x.area} • ${x.pain}/10</span><button class="btn" onclick="clearInjury(${S.injuries.indexOf(x)})">تم التعافي</button></div>`).join('')||'<div class="muted">ما في إصابة مسجلة.</div>'}</section>`}
function recoveryScore(){let n=S.sleep.at(-1);if(!n)return 70;return Math.max(0,Math.min(100,Math.round(100-(n.fatigue*5)-(n.pain*6)+Math.min(20,(n.hours-6)*5))))}function recoveryAdvice(){let s=recoveryScore();if(S.injuries.some(x=>!x.cleared)||s<45)return '🔴 التعافي / modified training. إذا الألم شديد أو غير معتاد، لا تتمرن عليه واطلب تقييماً طبياً.';if(s<70)return '🟡 خفف الحجم وركز على التقنية والنوم.';return '🟢 تدريب كامل مناسب إذا ما عندك أعراض أو إصابات.'}function saveRecovery(){S.sleep.push({date:today(),hours:+rh.value||7,fatigue:+rf.value||5,pain:+rp.value||0});save();render();toast('التعافي updated')}
function ai(){document.getElementById('view').innerHTML=`<section class="card"><div class="eyebrow">عقل المقاتل الذكي</div><h2>🧠 مدرب الذكاء الاصطناعي</h2><p class="muted">ارفع فيديو قصير. الـAI يأخذ لقطات من الفيديو، يحدد أخطاء تقنية قابلة للملاحظة، يعطيك تمارين تصحيح وخطة 7 أيام. مو بديل عن مدرب يشوفك مباشرة.</p><div class="field"><label>نوع الفيديو</label><select id="at"><option>Shadow الملاكمة</option><option>الضرب والتركيبات</option><option>حركة القدمين</option><option>المصارعة</option><option>الجراپلينغ</option><option>اللياقة</option></select></div><input id="av" type="file" accept="video/*"><div class="field"><label>سؤال للمدرب</label><textarea id="aq" placeholder="مثلاً: وين أكبر خطأ عندي؟"></textarea></div><div class="card" style="margin:10px 0"><b>🏅 الرانك القتالي</b><div class="big">${escapeHtml(S.rankEvaluation?.rank||'غير مصنف')}</div><p class="muted">${S.rankEvaluation?.status==='approved'?'تم اعتماد الرانك من تحليل AI.':'غير مصنف — ارفع فيديو أداء حتى يحدد AI تقييمك.'}</p></div><button class="btn primary" onclick="analyzeVideo()">🎥 أرسل الفيديو لتقييم الرانك</button><div id="air" class="section"></div></section><section class="section card"><h2>ملاحظات المدرب</h2>${S.coachNotes.slice(-8).reverse().map(x=>`<div style="padding:8px 0;border-bottom:1px solid var(--line)"><b>${x.date}</b><p>${x.text}</p></div>`).join('')||'<div class="empty">لا توجد ملاحظات.</div>'}</section>`}
function renderAIResult(j){let errors=(j.errors||[]).map((e,i)=>`<div class="card"><div class="row"><b>${i+1}. ${escapeHtml(e.issue||'تصحيح')}</b><span class="tag">${escapeHtml(e.severity||'متوسط')} • ${Math.round((Number(e.confidence)||0)*100)}%</span></div><p>${escapeHtml(e.why_it_matters||'')}</p><p class="warn">🎯 ${escapeHtml(e.cue||'ركز على التحكم وتكرار الحركة بثبات.')}</p></div>`).join('');let drills=(j.drills||[]).map(d=>`<div class="card"><b>🥊 ${escapeHtml(d.name||'تمرين')}</b><div class="muted">${escapeHtml(d.purpose||'')}</div><div>${escapeHtml(d.dose||'3 جولات')}</div><small class="muted">${escapeHtml(d.linked_error||'')}</small></div>`).join('');let plan=(j.seven_day_plan||[]).map((x,i)=>`<div class="scorebox"><b>اليوم ${i+1}</b><div>${escapeHtml(x)}</div></div>`).join('');return `<div class="card"><h3>🧠 ${escapeHtml(j.summary||'تحليل الفيديو')}</h3><p class="muted">التحليل مبني على لقطات من الفيديو؛ زاوية الكاميرا قد تخفي بعض التفاصيل.</p>${j.rank_assessment&&j.rank_assessment.rank?`<hr style="border-color:var(--line)"><h3>🏅 تقييم الرانك</h3><div class="big">${escapeHtml(j.rank_assessment.rank)}</div><p>Rating: <b>${Number(j.rank_assessment.rating)||0}</b> • الثقة: <b>${Math.round((Number(j.rank_assessment.confidence)||0)*100)}%</b></p><p class="muted">${escapeHtml(j.rank_assessment.reason||'')}</p>`:'<p class="warn">⚠️ لم يمنح AI رانك لأن الفيديو غير كافٍ للحكم.</p>'}</div><h3>⚠️ الأخطاء/الملاحظات</h3><div class="grid2">${errors||'<div class="card empty">ما ظهر خطأ واضح يمكن الجزم به من اللقطات.</div>'}</div><h3>🛠️ تمارين التصحيح</h3><div class="grid2">${drills||'<div class="empty">لا توجد تمارين مقترحة.</div>'}</div><h3>📅 خطة 7 أيام</h3><div class="scoregrid">${plan}</div><div class="card dangerbox"><b>🛡️ السلامة:</b> ${escapeHtml(j.safety||'لا تتمرن عبر ألم حاد أو غير معتاد، واستعن بمدرب للفحص المباشر.')}</div>`}
async function analyzeVideo(){let f=document.getElementById('av').files[0];if(!f)return toast('اختر فيديو');if(f.size>40e6)return toast('الفيديو أكبر من 40 ميغابايت');let out=document.getElementById('air');out.innerHTML='<div class="card">⏳ عم حلل الفيديو وأحوّله للقطات... ممكن ياخد شوي.</div>';let endpoint=S.settings.aiEndpoint;if(!endpoint){out.innerHTML='<div class="card airesult">حط رابط خادم الذكاء الاصطناعي من الإعدادات أولاً. ما رح اخترع تحليل من دون AI فعلي.</div>';return}try{let fd=new FormData();fd.append('video',f);fd.append('type',document.getElementById('at').value);fd.append('question',document.getElementById('aq').value);fd.append('mode','rank_assessment');fd.append('profile',JSON.stringify({stats:S.stats,skills:S.skills,dna:S.dna,level:S.level,profile:{age:S.age,height:S.height,weight:S.weight,experience:S.experience,goal:S.goal}}));fd.append('rank_policy','قيّم الأداء المرئي فقط. إذا كانت اللقطات كافية، أعد rank_assessment={rank,rating,confidence,reason}. إذا لم تكن كافية، أعد rank_assessment=null ولا تمنح Rank. لا تعتمد على إدخال اللاعب كناتج مهارة.');let r=await fetch(endpoint,{method:'POST',body:fd});let j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.detail||'خطأ في الخادم');if(j.rank_assessment&&j.rank_assessment.rank){let ra=j.rank_assessment;S.rankEvaluation={status:'approved',rating:Number(ra.rating)||0,rank:String(ra.rank),confidence:Number(ra.confidence)||0,videoDate:today(),videoType:document.getElementById('at').value,summary:String(ra.reason||ra.summary||'')};S.rank=S.rankEvaluation.rank;S.game.rating=S.rankEvaluation.rating;S.game.division=divisionFor(S.game.rating);S.history.push({date:today(),type:'rank_evaluation',name:'AI Rank Evaluation',xp:0,rank:S.rank,rating:S.game.rating});save()}out.innerHTML=renderAIResult(j);S.coachNotes.push({date:today(),text:JSON.stringify(j)});S.history.push({name:'تحليل فيديو بالذكاء الاصطناعي',date:today(),xp:15});S.xp+=15;save();toast('✅ التحليل وصل +15 خبرة')}catch(e){out.innerHTML='<div class="card dangerbox">تعذر تحليل الفيديو: '+escapeHtml(e.message||'خطأ في الخادم')+'<br><small>تأكد أن الخادم شغال وأن الرابط صحيح.</small></div>'}}
function coachBrain(){let e=Object.entries(S.stats).sort((a,b)=>b[1]-a[1]),weak=e[e.length-1],strong=e[0];let style=S.skills.takedown+S.skills.guard>S.skills.jab+S.skills.combos?'متخصص أكثر بالجراپلينغ':'متخصص أكثر بالضرب';S.dna={style, strength:labels[strong[0]]+' • '+Math.round(strong[1]),weakness:labels[weak[0]]+' • '+Math.round(weak[1]),priority:'الأيام السبعة القادمة: '+labels[weak[0]]};save();document.getElementById('air').innerHTML='<div class="card"><h3>عقل المقاتل</h3><p>الأسلوب: <b>'+style+'</b></p><p>القوة: '+labels[strong[0]]+'</p><p>نقطة الضعف: '+labels[weak[0]]+'</p><p>الأولوية: '+labels[weak[0]]+'</p></div>';toast('🧠 DNA updated')}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function profile(){document.getElementById('view').innerHTML=`<section class="card"><h2>⚙️ مقاتل الملف الشخصي</h2><div class="field"><label>اسم اللاعب</label><input id="pn" value="${S.name}"></div><div class="grid2"><div class="field"><label>العمر</label><input id="pa" type="number" min="13" max="100" value="${S.age||21}"></div><div class="field"><label>الطول سم</label><input id="ph" type="number" value="${S.height||175}"></div><div class="field"><label>الوزن كغ</label><input id="pw" type="number" value="${S.weight||70}"></div><div class="field"><label>أيام التدريب</label><input id="pd" type="number" min="1" max="7" value="${S.daysPerWeek}"></div><div class="field"><label>مدة الحصة</label><input id="pm" type="number" min="15" max="240" value="${S.sessionMin}"></div><div class="field"><label>الخبرة</label><select id="pe"><option value="beginner" ${S.experience==='beginner'?'selected':''}>مبتدئ</option><option value="intermediate" ${S.experience==='intermediate'?'selected':''}>متوسط</option><option value="advanced" ${S.experience==='advanced'?'selected':''}>متقدم</option></select></div></div><div class="field"><label>هدفك</label><textarea id="pg">${S.goal}</textarea></div><button class="btn primary" onclick="saveProfile()">حفظ</button> <button class="btn" onclick="notifyMe()">🔔 الإشعارات</button> <button class="btn" onclick="openCloud()">☁️ Google / السحابة</button> <button class="btn blue" onclick="openAISettings()">🤖 خادم الذكاء الاصطناعي</button></section><section class="section card"><h2>🩹 وضع الإصابة</h2><div class="grid2"><div class="field"><label>المنطقة</label><input id="ia" placeholder="مثلاً كتف"></div><div class="field"><label>الألم 0–10</label><input id="ip" type="number" min="0" max="10" value="3"></div></div><button class="btn danger" onclick="addInjury()">تفعيل وضع التعافي</button></section><section class="section card"><h2>💾 البيانات</h2><button class="btn" onclick="exportData()">تصدير نسخة احتياطية</button> <button class="btn" onclick="importData()">استيراد نسخة احتياطية</button> <button class="btn danger" onclick="resetAll()">إعادة ضبط</button></section>`}
function saveProfile(){S.name=pn.value.trim()||'لاعب';S.age=+pa.value||21;S.height=+ph.value||175;S.weight=+pw.value||70;S.daysPerWeek=+pd.value||4;S.sessionMin=+pm.value||60;S.experience=pe.value;S.goal=pg.value.trim()||S.goal;S.profileComplete=true;save();render();toast('تم حفظ الملف')}function addInjury(){let area=ia.value.trim(),pain=+ip.value;if(!area)return toast('اكتب المنطقة');S.injuries.push({area,pain,date:today(),cleared:false});S.missions=[];save();render();toast('التعافي Mode ON')}function clearInjury(i){S.injuries[i].cleared=true;S.missions=[];save();render()}
function openAssessment(){showModal(`<h2>📏 اختبار البداية</h2><p class="muted">هذا الاختبار يبني خط الأساس البدني فقط. لا يعطي Rank ولا Rating. الرانك القتالي يحتاج فيديو وتحليل AI.</p><div class="grid2">${[['pushups','Push-ups'],['pullups','Pull-ups'],['run','1.5km Run (دقيقة)'],['plank','Plank (sec)']].map(x=>`<div class="field"><label>${x[1]}</label><input id="a_${x[0]}" type="number" min=0></div>`).join('')}</div><button class="btn primary" onclick="finishAssessment()">حفظ خط الأساس</button>`)}
function finishAssessment(){let p=+a_pushups.value||0,pu=+a_pullups.value||0,r=+a_run.value||0,pl=+a_plank.value||0;S.tests={pushups:p,pullups:pu,run:r,plank:pl};S.stats.strength=Math.min(100,Math.round(p*.35+pu*.8));S.stats.cardio=Math.min(100,Math.max(0,Math.round(100-Math.max(0,r)*4)));S.stats.discipline=Math.min(100,S.stats.discipline+1);S.history.push({date:today(),type:'test',name:'اختبار خط الأساس',xp:0});save();closeModal();render();toast('📏 تم حفظ خط الأساس — الرانك ما زال بانتظار AI')}
function bossModal(){showModal(`<h2>👹 ${bossName()}</h2><p>اختبار اختياري. لا تعمل Boss إذا عندك إصابة أو التعافي score منخفض.</p><div class="field"><label>نتيجتك %</label><input id="bs" type="number" min="0" max="100" value="70"></div><button class="btn danger" onclick="let s=+bs.value;if(s>=80){addXP(500);toast('👹 BOSS DEFEATED +500 خبرة')}else{addXP(150);toast('صمد الزعيم • +150 خبرة')};S.bosses.push({date:today(),name:bossName(),score:s});save();closeModal();render()">إرسال</button>`)}
