function openAuth(){showModal(`<h2>🔐 حساب اللاعب</h2><p class="muted">حسابك يحفظ تقدمك على السحابة ويمكنك فتحه من أي جهاز. يمكنك استخدام Google أو البريد الإلكتروني.</p><div class="field"><label>البريد الإلكتروني</label><input id="authEmail" type="email" placeholder="you@example.com"></div><div class="field"><label>كلمة المرور</label><input id="authPass" type="password" minlength="6" placeholder="6 أحرف على الأقل"></div><button class="btn primary" onclick="emailSignIn(false)">دخول</button> <button class="btn green" onclick="emailSignIn(true)">إنشاء حساب</button><button class="btn blue" onclick="googleSignIn()">Google</button><hr><div class="field"><label>إعدادات Firebase (للمطور/النشر)</label><textarea id="fc" placeholder='{"apiKey":"...","authDomain":"...","projectId":"..."}'></textarea></div><button class="btn" onclick="saveFirebase()">حفظ Config</button>`)}
function saveFirebase(){try{S.settings.firebase=JSON.parse(fc.value);save();toast('إعدادات Firebase saved');closeModal()}catch(e){toast('JSON غير صالح')}}
async function initFirebase(){
 if(!S.settings.firebase) throw Error('إعدادات Firebase missing');
 const appmod=await import('https://www.gstatic.com/firebasejs/11.10.0/firebase-app.js');
 const authmod=await import('https://www.gstatic.com/firebasejs/11.10.0/firebase-auth.js');
 const fs=await import('https://www.gstatic.com/firebasejs/11.10.0/firebase-firestore.js');firebaseFs=fs;window.__mmaFS=fs;
 if(!firebaseApp){firebaseApp=appmod.initializeApp(S.settings.firebase,'mma-project-s');firebaseAuth=authmod.getAuth(firebaseApp);firebaseDb=fs.getFirestore(firebaseApp);}
 return {authmod,fs};
}
async function googleSignIn(){
 if(!S.settings.firebase){toast('أضف إعدادات Firebase أولاً');return}
 try{
  const {authmod,fs}=await initFirebase();
  const p=new authmod.GoogleAuthProvider();
  const r=await authmod.signInWithPopup(firebaseAuth,p);currentUser=r.user;
  S.name=r.user.displayName||S.name;S.settings.cloud=true;
  await cloudLoadOrCreate(fs,r.user.uid);save();closeModal();render();toast('☁️ تم ربط Google');
 }catch(e){toast('فشل تسجيل Google: '+e.message)}
}
async function emailSignIn(create){
 if(!S.settings.firebase){toast('أضف إعدادات Firebase أولاً');return}
 try{const {authmod,fs}=await initFirebase();const email=document.getElementById('authEmail').value.trim();const pass=document.getElementById('authPass').value;if(!email||pass.length<6){toast('أدخل بريد صحيح وكلمة مرور 6 أحرف على الأقل');return}const r=create?await authmod.createUserWithEmailAndPassword(firebaseAuth,email,pass):await authmod.signInWithEmailAndPassword(firebaseAuth,email,pass);currentUser=r.user;S.name=r.user.displayName||S.name;S.settings.cloud=true;await cloudLoadOrCreate(fs,r.user.uid);save();closeModal();render();toast(create?'🎉 تم إنشاء الحساب':'☁️ تم تسجيل الدخول')}catch(e){toast('تعذر تسجيل الدخول: '+(e.code||e.message))}}
function openOnboarding(){showModal(`<h2>🥊 أنشئ مقاتلك من الصفر</h2><p class="muted">ما في اسم أو تقييم أو Rank جاهز. أنت بتبني ملفك من الصفر، وبعدها تقييم الرانك القتالي يتم حصراً عبر تحليل فيديو بالذكاء الاصطناعي.</p><div class="grid2"><div class="field"><label>اسم اللاعب</label><input id="obName" placeholder="اكتب اسمك"></div><div class="field"><label>العمر</label><input id="obAge" type="number" min=13 max=100></div><div class="field"><label>الطول (سم)</label><input id="obHeight" type="number" min=100 max=230></div><div class="field"><label>الوزن (كغ)</label><input id="obWeight" type="number" min=30 max=250></div><div class="field"><label>خبرتك</label><select id="obExp"><option value="">اختر</option><option value="beginner">مبتدئ</option><option value="intermediate">متوسط</option><option value="advanced">متقدم</option></select></div><div class="field"><label>أيام التدريب بالأسبوع</label><input id="obDays" type="number" min=1 max=7></div><div class="field"><label>مدة الحصة بالدقائق</label><input id="obMin" type="number" min=10 max=240></div><div class="field"><label>الهدف الرئيسي</label><select id="obGoal"><option value="">اختر</option><option>مقاتل MMA شامل</option><option>قوة وبناء جسم</option><option>مهارات كالستنكس</option><option>لياقة وخسارة دهون</option><option>تحضير لنزال</option></select></div></div><button class="btn primary" onclick="finishOnboarding()">🚀 ابدأ من الصفر</button>`)}
function finishOnboarding(){let name=obName.value.trim();if(!name||!obAge.value||!obHeight.value||!obWeight.value||!obExp.value||!obDays.value||!obMin.value||!obGoal.value)return toast('كمّل معلوماتك كلها أولاً');S.name=name;S.age=+obAge.value;S.height=+obHeight.value;S.weight=+obWeight.value;S.experience=obExp.value;S.daysPerWeek=+obDays.value;S.sessionMin=+obMin.value;S.goal=obGoal.value;S.profileComplete=true;S.started=true;S.rank='غير مصنف';S.rankEvaluation={status:'pending',rating:0,rank:'غير مصنف',confidence:0,videoDate:null,videoType:null,summary:''};S.stats=Object.fromEntries(Object.keys(base.stats).map(k=>[k,0]));S.skills=Object.fromEntries(Object.keys(base.skills).map(k=>[k,0]));S.game=structuredClone(base.game);S.smartPlan={date:null,items:[],completed:[]};S.missions=[];save();closeModal();generate();render();toast('🔥 تم إنشاء مقاتلك من الصفر')}
async function cloudLoadOrCreate(fs,uid){
 try{
  const {doc,getDoc}=fs; const ref=doc(firebaseDb,'fighters',uid); const snap=await getDoc(ref);
  if(snap.exists()){
   const remote=snap.data();
   const keep={...S.settings};
   if(Number(remote.schemaVersion||0)<18){S=structuredClone(base);S.settings=Object.assign(base.settings,keep);await cloudSave(firebaseDb,uid);toast('☁️ تم بدء ملفك من الصفر وفق النظام الجديد');return}
   S=Object.assign(structuredClone(base),remote);S.settings=Object.assign(base.settings,S.settings||{},keep);save();toast('☁️ التقدم loaded');
  } else await cloudSave(firebaseDb,uid);
 }catch(e){toast('فشل تحميل السحابة')}
}
async function cloudSave(db,uid){
 if(syncBusy)return; syncBusy=true;
 try{
  const {doc,setDoc}=await import('https://www.gstatic.com/firebasejs/11.10.0/firebase-firestore.js');
  const payload=JSON.parse(JSON.stringify(S));payload.schemaVersion=18;payload._meta={updatedAt:new Date().toISOString(),appVersion:'V18.0'};
  await setDoc(doc(db,'fighters',uid),payload,{merge:true});
 }catch(e){toast('فشل حفظ السحابة')}finally{syncBusy=false}
}
async function cloudLogout(){try{if(firebaseAuth){const {signOut}=await import('https://www.gstatic.com/firebasejs/11.10.0/firebase-auth.js');await signOut(firebaseAuth)}}catch(e){}currentUser=null;S.settings.cloud=false;save();render();toast('Signed out')}
