function exportData(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(S,null,2)],{type:'application/json'}));a.download='mma-project-s-backup.json';a.click()}function importData(){let i=document.createElement('input');i.type='file';i.accept='.json';i.onchange=()=>{let r=new FileReader();r.onload=()=>{try{S=Object.assign(structuredClone(base),JSON.parse(r.result));save();render();toast('تم الاستيراد')}catch(e){toast('النسخة الاحتياطية غير صالحة')}};r.readAsText(i.files[0])};i.click()}function resetAll(){if(confirm('حذف كل التقدم المحلي?')){localStorage.removeItem(KEY);location.reload()}}
