const SMART_SKILL_LANES=[
 {name:'🥊 الملاكمة',key:'boxing'}, {name:'🦵 الكيك بوكسينغ',key:'kickboxing'}, {name:'🇹🇭 مواي تاي',key:'muaythai'}, {name:'🤼 المصارعة',key:'wrestling'}, {name:'🥋 BJJ',key:'bjj'}, {name:'⚔️ MMA',key:'mma'}
];
function readinessScore(){let n=S.sleep.at(-1);if(!n)return S.readiness.score||70;let r=100-(n.fatigue*5)-(n.pain*7)+Math.min(20,(n.hours-7)*6);if(S.injuries.some(x=>!x.cleared))r-=20;return Math.max(0,Math.min(100,Math.round(r)))}
function trainingMode(){let r=readinessScore(),since=Date.now()-7*86400000,recent=(S.history||[]).filter(x=>x.date&&new Date(x.date).getTime()>=since&&['session','technique','calisthenics','smart'].includes(x.type)).length;if(S.injuries.some(x=>!x.cleared)||r<40)return 'recovery';if(recent>=Math.max(4,S.daysPerWeek+1))return 'light';return r<60?'light':r<80?'normal':'hard'}
function currentCali(){for(const g of CALI){for(let i=0;i<g[3].length;i++){if(caliUnlocked(g,i)&&!caliDone(g,i))return {g,i,v:g[3][i]}}}return null}
function nextSportSkill(groupName){let group=Object.keys(SPORT_SKILLS).find(g=>g.includes(groupName));if(!group)return null;let arr=SPORT_SKILLS[group];for(let i=0;i<arr.length;i++){if(techniqueUnlocked(group,i)&&!techniqueDone(group,i))return {group,i,name:arr[i][1]}}return null}
function buildSmartPlan(){let mode=trainingMode(),r=readinessScore(),items=[],lanes=SMART_SKILL_LANES.slice().sort((a,b)=>(S.stats[a.key]||5)-(S.stats[b.key]||5));
 if(mode==='recovery')items=[{icon:'🫀',title:'Recovery Session',desc:'20–35 دقيقة مشي خفيف + تنفس + Mobility لطيف',type:'recovery',xp:35},{icon:'🧠',title:'مراجعة ذهنية',desc:'10 دقائق تصور تقني بدون إجهاد',type:'iq',xp:25}];
 else {for(const lane of lanes.slice(0,2)){let a=nextSportSkill(lane.name);if(a)items.push({icon:'🎯',title:lane.name+' • '+a.name,desc:'20–35 دقيقة تقنية بجودة عالية',type:'tech',group:a.group,index:a.i,xp:70})}let cal=currentCali();if(cal)items.push({icon:'🤸',title:'كالستنكس • '+cal.v[0],desc:'20–30 دقيقة تدرج مهارة + تمارين مساعدة لبناء الجسم',type:'cali',group:cal.g[0],index:cal.i,xp:70});items.push({icon:'🫁',title:'Conditioning',desc:mode==='hard'?'8–12 جولة قصيرة مع راحة كافية':'6–8 جولات معتدلة بدون إنهاك',type:'conditioning',xp:55});items.push({icon:'🧘',title:'Mobility + Prehab',desc:'10–15 دقيقة للكتف والورك والكاحل والعمود الفقري',type:'mobility',xp:35});if(mode==='hard')items.push({icon:'🧠',title:'Fight IQ',desc:'10 دقائق تحليل جولة أو تصور مواقف وقرارات',type:'iq',xp:30})}
 return {date:today(),mode,readiness:r,items,completed:[]};}
function ensureSmartPlan(){if(!S.smartPlan||S.smartPlan.date!==today()){S.smartPlan=buildSmartPlan();save()}return S.smartPlan}
function completeSmart(i){let p=ensureSmartPlan();if(p.completed.includes(i))return;let x=p.items[i];if(!x)return;p.completed.push(i);if(x.type==='tech')trainTechnique(x.group,x.index);else if(x.type==='cali')trainCali(x.group,x.index);else{addXP(x.xp);S.history.push({date:today(),type:'smart',name:x.title,xp:x.xp});}save();render();toast('✅ '+x.title+' مكتمل')}
function refreshSmart(){S.smartPlan=buildSmartPlan();save();render();toast('🧭 تم تحديث الخطة حسب حالتك')}
function smartView(){let p=ensureSmartPlan(),done=p.completed.length,total=p.items.length;document.getElementById('view').innerHTML=`<section class="card"><div class="eyebrow">المحرك المركزي</div><h2>🧭 خطة اليوم الذكية</h2><div class="smartgrid"><div class="scorebox"><small>الجاهزية</small><div class="readiness">${p.readiness}</div><span class="muted">/100</span></div><div class="scorebox"><small>النمط</small><div class="big">${p.mode==='hard'?'قوي':p.mode==='normal'?'طبيعي':p.mode==='light'?'خفيف':'تعافي'}</div></div><div class="scorebox"><small>المهام</small><div class="big">${done}/${total}</div></div><div class="scorebox"><small>المستوى</small><div class="big">${S.level}</div></div></div><p class="muted">الخطة تتغير تلقائياً حسب الجاهزية، نقاط الضعف، المهارات المفتوحة والإصابات المسجلة. الراحة جزء من التطور.</p><button class="btn blue" onclick="refreshSmart()">🔄 إعادة بناء الخطة</button></section><section class="section">${p.items.map((x,i)=>`<div class="planitem ${p.completed.includes(i)?'done':''}" style="margin-bottom:9px"><div class="row"><div><h3 style="margin:0">${x.icon} ${x.title}</h3><p class="muted">${x.desc}</p></div><span class="tag">+${x.xp} XP</span></div>${p.completed.includes(i)?'<b class="success">✓ مكتملة</b>':`<button class="btn primary" onclick="completeSmart(${i})">ابدأ / أكمل</button>`}</div>`).join('')}</section><section class="section grid2"><div class="card"><h3>🏆 قدرات النظام</h3><p class="muted">قوة نسبية وقوة عامة • انفجار • سرعة • تحمل هوائي ولاهوائي • حركة • توازن • قبضة • كور • مهارات ضرب وجراپلينغ • ذكاء قتالي.</p></div><div class="card"><h3>🛡️ قاعدة التقدم</h3><p class="muted">الجودة قبل السرعة، والتدرج قبل المهارات المتقدمة، ولا يوجد تدريب قسري فوق ألم أو إصابة.</p></div></section>`}
function advancedTesting(){showModal(`<h2>📏 اختبار القدرات</h2><p class="muted">اختبر فقط وأنت مرتاح وبدون ألم. الاختبار دوري وليس يومياً.</p><div class="grid2">${[['broadJump','Broad Jump cm'],['verticalJump','Vertical Jump cm'],['deadHang','Dead Hang sec'],['burpees','Burpees / 2 min'],['shuttle','Shuttle 5-10-5 sec'],['sidePlank','Side Plank sec/side']].map(([k,l])=>`<div class="field"><label>${l}</label><input id="tx_${k}" type="number" min="0" step="0.1" value="${S.testsAdvanced[k]||0}"></div>`).join('')}</div><button class="btn primary" onclick="saveAdvancedTests()">حفظ القياسات</button>`)}
function saveAdvancedTests(){Object.keys(S.testsAdvanced).forEach(k=>S.testsAdvanced[k]=+document.getElementById('tx_'+k).value||0);S.history.push({date:today(),type:'test',name:'اختبار القدرات الشامل',xp:100});addXP(100);save();closeModal();render();toast('📏 تم تحديث خط الأساس')}

// ===== V17 GAME / COMPETITION LAYER =====
const GAME_BADGES=[
 ['first','🥊','أول حصة','أكمل أول حصة تدريبية'],['streak7','🔥','7 أيام','حافظ على سلسلة 7 أيام'],['quest25','🎯','صياد المهام','أكمل 25 مهمة'],['level10','⚡','المستوى 10','وصل للمستوى 10'],['boss3','👹','قاتل الزعماء','أكمل 3 مواجهات زعيم'],['test','📏','المختبر','سجّل اختبار قدرات شامل'],['season','🏆','منافس الموسم','اجمع 1000 نقطة موسم'],['legend','👑','أسطورة','وصل للمستوى 30']
];
function seasonId(){let d=new Date(),q=Math.floor(d.getMonth()/3)+1;return `${d.getFullYear()}-S${q}`}
function weekId(){let d=new Date(),one=new Date(d.getFullYear(),0,1),n=Math.ceil((((d-one)/86400000)+one.getDay()+1)/7);return `${d.getFullYear()}-W${n}`}function weekStartDate(){let d=new Date();d.setHours(0,0,0,0);let day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d.toISOString().slice(0,10)}
function divisionFor(r){if(!r)return 'غير مصنف';return r>=1800?'Diamond':r>=1600?'Platinum':r>=1400?'Gold':r>=1200?'Silver':'Bronze'}
function ensureGame(){
 if(!S.game)S.game=structuredClone(base.game);let sid=seasonId(),wid=weekId();
 if(S.game.seasonId!==sid){S.game.seasonId=sid;S.game.seasonPoints=0;S.game.claimed=[];S.game.daily=[];S.game.weekly=[]}
 if(S.game.weeklyStart!==wid){S.game.weeklyStart=wid;S.game.weeklyXP=0;S.game.weekly=[]}
 S.game.division=divisionFor(S.game.rating);save();
}
function trackGameXP(xp){ensureGame();let mult=eventOfDay()==='مهمة خبرة مضاعفة'?2:1;S.game.seasonPoints+=Math.max(1,Math.round(xp/4))*mult;S.game.weeklyXP+=xp;S.game.division=divisionFor(S.game.rating)}
function gameReward(kind,xp=0){ensureGame();S.game.coins+=(kind==='boss'?30:kind==='challenge'?20:10);S.game.division=divisionFor(S.game.rating);checkGameBadges();save();return xp}
function checkGameBadges(){let q=S.history.filter(x=>x.type==='quest').length,b=S.bosses?.filter(x=>x.completed).length||0;
 const got={first:S.history.some(x=>['session','technique','calisthenics','smart'].includes(x.type)),streak7:S.streak>=7,quest25:q>=25,level10:S.level>=10,boss3:b>=3,test:S.history.some(x=>x.type==='test'),season:S.game.seasonPoints>=1000,legend:S.level>=30};
 GAME_BADGES.forEach(x=>{if(got[x[0]]&&!S.game.badges.includes(x[0])){S.game.badges.push(x[0]);S.game.coins+=50;toast('🏅 شارة جديدة: '+x[1]+' '+x[2])}})
}
function dailyChallenges(){ensureGame();let d=new Date().getDay();let pool=[
 ['shadow','🥊 Shadow Fighter','أكمل مهمة Shadow/Boxing اليوم',()=>S.history.some(x=>x.date===today()&&/Shadow|Boxing/i.test(x.name||'')),100],
 ['smart','🧭 Smart Day','أكمل مهمتين من الخطة الذكية',()=>ensureSmartPlan().completed.length>=2,120],
 ['fitness','💪 Engine','سجّل تمرين لياقة أو قوة اليوم',()=>S.history.some(x=>x.date===today()&&['session','fitness','calisthenics'].includes(x.type)),100],
 ['iq','🧠 Fight IQ','أكمل مهمة ذكاء قتالي',()=>S.history.some(x=>x.date===today()&&/ذكاء|IQ/i.test(x.name||'')),90],
 ['discipline','⚔️ No Zero Day','أنجز أي مهمة تدريبية اليوم',()=>S.history.some(x=>x.date===today()),80],
 ['recovery','🫀 Recovery','سجّل تعافي/نوم اليوم',()=>S.sleep.some(x=>x.date===today()),70],
 ];
 return [pool[d%pool.length],pool[(d+2)%pool.length],pool[(d+4)%pool.length]].map(x=>({id:x[0],title:x[1],desc:x[2],done:!!x[3](),xp:x[4]}))
}
function weeklyChallenges(){let q=Math.floor(new Date().getDate()/7);return [
 {id:'wxp',title:'⚡ أسبوع الخبرة',desc:'اجمع 600 XP خلال الأسبوع',progress:Math.min(600,S.game.weeklyXP),target:600,xp:250},
 {id:'wq',title:'🎯 أسبوع المهام',desc:'أكمل 12 مهمة',progress:Math.min(12,S.history.filter(x=>x.date>=weekStartDate()).filter(x=>x.type==='quest').length),target:12,xp:300},
 {id:'wskill',title:'🌳 تطوير مهارة',desc:'ارفع أي مهارة قتالية 3 مرات',progress:Math.min(3,S.history.filter(x=>x.date>=weekStartDate()&&['technique','smart'].includes(x.type)).length),target:3,xp:220}
]}
function challengeDone(id){let d=dailyChallenges().find(x=>x.id===id);return d?.done||false}
function claimChallenge(id,weekly=false){ensureGame();let key=(weekly?'w:':'d:')+weekId()+':'+id;if(S.game.claimed.includes(key))return toast('المكافأة مأخوذة');let c=weekly?weeklyChallenges().find(x=>x.id===id):dailyChallenges().find(x=>x.id===id);if(!c)return;if(weekly?(c.progress<c.target):!c.done)return toast('كمّل التحدي أولاً');S.game.claimed.push(key);addXP(c.xp);gameReward('challenge',c.xp);toast('🎁 مكافأة التحدي +'+c.xp+' XP');render()}
async function publishLeaderboard(){if(!firebaseDb||!currentUser)return false;try{let fs=window.__mmaFS;if(!fs)return false;let ref=fs.doc(firebaseDb,'leaderboard',currentUser.uid);await fs.setDoc(ref,{uid:currentUser.uid,name:(S.name||'Fighter').slice(0,24),level:S.level,xp:S.xp,rating:S.game.rating,rank:S.rank,division:S.game.division,rankStatus:S.rankEvaluation?.status||'pending',seasonId:S.game.seasonId,seasonPoints:S.game.seasonPoints,weeklyXP:S.game.weeklyXP,badges:S.game.badges.length,updatedAt:Date.now()},{merge:true});return true}catch(e){console.warn('leaderboard publish',e);return false}}
async function loadLeaderboard(){if(!firebaseDb||!window.__mmaFS)return [];try{let fs=window.__mmaFS;let q=fs.query(fs.collection(firebaseDb,'leaderboard'),fs.orderBy('seasonPoints','desc'),fs.limit(100));let snap=await fs.getDocs(q);return snap.docs.map(x=>x.data()).filter(x=>x.seasonId===seasonId()).slice(0,50)}catch(e){console.warn('leaderboard load',e);return []}}
async function refreshLeaderboard(){let box=document.getElementById('lb');if(!box)return;box.innerHTML='<div class="empty">⏳ عم حمّل الترتيب...</div>';let rows=await loadLeaderboard();if(!rows.length){box.innerHTML='<div class="empty">الترتيب العالمي يظهر بعد تفعيل Firebase وتسجيل لاعبين.</div>';return}box.innerHTML=rows.map((r,i)=>`<div class="leaderrow ${currentUser&&r.uid===currentUser.uid?'me':''}"><div class="pos">#${i+1}</div><div><b>${escapeHtml(r.name||'Fighter')}</b><div class="muted">Lv.${r.level||1} • ${r.division||'غير مصنف'} • ${r.rating||0} Rating • ${r.rank||'غير مصنف'}</div></div><strong>${r.seasonPoints||0} SP</strong></div>`).join('')}
async function arena(){ensureGame();checkGameBadges();let ds=dailyChallenges(),ws=weeklyChallenges();let pct=Math.min(100,Math.round((S.game.seasonPoints/1000)*100));let badges=S.game.badges.map(id=>GAME_BADGES.find(x=>x[0]===id)).filter(Boolean);document.getElementById('view').innerHTML=`<section class="card gamehero"><div class="eyebrow">MMA ARENA • ${S.game.seasonId}</div><div class="row"><div><h1>🏆 ساحة المقاتلين</h1><p class="muted">تحديات حركات وشادو بوكس • موسم • ترتيب نقاط • شارات • الرانك القتالي يعتمد على AI</p></div><span class="division">${S.game.division}</span></div><div class="gamegrid"><div class="scorebox"><small>Rating</small><div class="gameStat">${S.game.rating}</div></div><div class="scorebox"><small>نقاط الموسم</small><div class="gameStat">${S.game.seasonPoints}</div></div><div class="scorebox"><small>Coins</small><div class="gameStat">🪙 ${S.game.coins}</div></div><div class="scorebox"><small>هذا الأسبوع</small><div class="gameStat">${S.game.weeklyXP} XP</div></div></div><div class="seasonbar"><i style="width:${pct}%"></i></div><small class="muted">نقاط الموسم للعبة والتحديات. أما الرانك القتالي فلا يتغير من النقاط؛ لا يُمنح إلا بعد تحليل فيديو بالذكاء الاصطناعي.</small></section>
<section class="section grid2"><div class="card"><div class="row"><h2>⚔️ تحديات اليوم</h2><span class="tag">تتجدد يومياً</span></div>${ds.map(c=>{let key='d:'+weekId()+':'+c.id,claimed=S.game.claimed.includes(key);return `<div class="challenge ${c.done?'done':''}" style="margin-top:8px"><div class="row"><div><b>${c.title}</b><div class="muted">${c.desc}</div></div><span class="tag">+${c.xp} XP</span></div><button class="btn ${c.done?'green':''}" style="margin-top:8px" onclick="claimChallenge('${c.id}')">${claimed?'✓ مأخوذة':c.done?'🎁 استلم المكافأة':'🔒 أكمل التحدي'}</button></div>`}).join('')}</div>
<div class="card"><div class="row"><h2>📅 تحديات الأسبوع</h2><span class="tag">${S.game.weeklyXP} XP</span></div>${ws.map(c=>{let key='w:'+weekId()+':'+c.id,claimed=S.game.claimed.includes(key);return `<div class="challenge" style="margin-top:8px"><b>${c.title}</b><div class="muted">${c.desc}</div><div class="bar" style="margin:8px 0"><i style="width:${Math.min(100,c.progress/c.target*100)}%"></i></div><div class="row"><small>${c.progress}/${c.target}</small><button class="btn gold" onclick="claimChallenge('${c.id}',true)">${claimed?'✓':c.progress>=c.target?'🎁':'🔒'}</button></div></div>`}).join('')}</div></section>
<section class="section grid2"><div class="card"><div class="row"><h2>🌍 الترتيب العالمي</h2><button class="btn" onclick="refreshLeaderboard()">↻</button></div><div id="lb"><div class="empty">اضغط تحديث لعرض ترتيب الموسم.</div></div><button class="btn blue" onclick="publishLeaderboard().then(()=>refreshLeaderboard())">☁️ تحديث مركزي</button></div><div class="card"><h2>🏅 مجموعتي</h2><p class="muted">الشارات التي جمعتها:</p><div style="display:flex;gap:6px;flex-wrap:wrap">${badges.length?badges.map(b=>`<span class="badge">${b[1]} ${b[2]}</span>`).join(''):'<span class="muted">ابدأ أول تحدي لتحصل على أول شارة.</span>'}</div><hr style="border-color:var(--line);margin:14px 0"><p class="muted">السبارينغ للتطور والتحليل، وليس لرفع الترتيب بمجرد إدخال فوز ذاتي. الـRating التنافسي يبقى منفصلاً عن السجل التدريبي.</p><button class="btn primary" onclick="arenaMatchModal()">🥋 تسجيل سبارينغ</button></div></section>`}
function arenaMatchModal(){showModal(`<h2>🥋 تسجيل سبارينغ</h2><p class="muted">سجّل الجولة لتحليل تقدمك. هذا السجل لا يغيّر Rating التنافسي.</p><div class="grid3"><div class="field"><label>الجولات</label><input id="amr" type="number" min="1" value="3"></div><div class="field"><label>مدة الجولة بالدقائق</label><input id="amm" type="number" min="1" value="3"></div><div class="field"><label>الشدة 1–10</label><input id="ami" type="number" min="1" max="10" value="6"></div></div><div class="grid2"><div class="field"><label>شو نجح؟</label><textarea id="amgood" placeholder="مثلاً: الجاب والدفاع"></textarea></div><div class="field"><label>شو يحتاج تطوير؟</label><textarea id="ambad" placeholder="مثلاً: الدفاع ضد الإسقاط"></textarea></div></div><button class="btn primary" onclick="recordArenaMatch()">حفظ السبارينغ</button>`)}
function recordArenaMatch(){let rounds=Math.max(1,+document.getElementById('amr').value||3),minutes=Math.max(1,+document.getElementById('amm').value||3),intensity=Math.max(1,Math.min(10,+document.getElementById('ami').value||6)),good=document.getElementById('amgood').value.trim(),bad=document.getElementById('ambad').value.trim();let xp=Math.min(180,40+rounds*12);S.sparring.push({date:today(),rounds,minutes,intensity,good,bad,source:'arena_log'});S.history.push({date:today(),type:'sparring',name:'Arena Sparring',xp});addXP(xp);gameReward('challenge',xp);save();closeModal();render();toast('🥋 تم حفظ السبارينغ +'+xp+' XP')}

function updateNetworkStatus(){const el=document.getElementById('netStatus');if(!el)return;const online=navigator.onLine;el.textContent=online?'● متصل':'○ بدون إنترنت';el.style.color=online?'var(--green)':'var(--warn)'}
window.addEventListener('online',()=>{updateNetworkStatus();toast('🌐 عاد الاتصال');if(currentUser&&firebaseDb)cloudSave(firebaseDb,currentUser.uid)});window.addEventListener('offline',()=>{updateNetworkStatus();toast('📴 وضع عدم الاتصال — تقدمك محفوظ محلياً')});
function render(){updateNetworkStatus();document.getElementById('streak').textContent='🔥 '+S.streak;if(!S.profileComplete){document.getElementById('nav').innerHTML='';document.getElementById('view').innerHTML='<section class="card" style="margin-top:40px;text-align:center"><div class="eyebrow">MMA SYSTEM</div><h1>🥊 ابنِ مقاتلك من الصفر</h1><p class="muted">لا اسم جاهز، لا Rating، لا Rank. ابدأ ببياناتك ثم طوّر مهاراتك.</p><button class="btn primary" onclick="openOnboarding()">🚀 إنشاء ملف المقاتل</button></section>';return}nav();document.getElementById('authBtn').textContent=currentUser?(currentUser.displayName||'Google ✓'):t('login');document.getElementById('authBtn').textContent=currentUser?(currentUser.displayName||'Google ✓'):t('login');document.getElementById('installBtn')?.classList.toggle('hidden',!installPrompt);if(tab==='home')home();if(tab==='arena')arena();if(tab==='smart')smartView();if(tab==='training')training();if(tab==='calisthenics')caliView();if(tab==='fitness')fitnessView();if(tab==='skills')skills();if(tab==='stats')stats();if(tab==='sparring')sparring();if(tab==='progress')progress();if(tab==='camp')camp();if(tab==='nutrition')nutrition();if(tab==='recovery')recovery();if(tab==='ai')ai();if(tab==='profile')profile()}
async function initAuth(){if(!S.settings.firebase)return;try{const appmod=await import('https://www.gstatic.com/firebasejs/11.10.0/firebase-app.js');const authmod=await import('https://www.gstatic.com/firebasejs/11.10.0/firebase-auth.js');const fs=await import('https://www.gstatic.com/firebasejs/11.10.0/firebase-firestore.js');firebaseFs=fs;window.__mmaFS=fs;if(!firebaseApp){firebaseApp=appmod.initializeApp(S.settings.firebase,'mma-project-s');firebaseAuth=authmod.getAuth(firebaseApp);firebaseDb=fs.getFirestore(firebaseApp);}authmod.onAuthStateChanged(firebaseAuth,async u=>{currentUser=u;if(u){S.name=u.displayName||S.name;S.settings.cloud=true;await cloudLoadOrCreate(fs,u.uid);}else{S.settings.cloud=false;}save();render()})}catch(e){console.warn('تهيئة Firebase',e)}}
window.addEventListener('load',async()=>{document.documentElement.lang='ar';document.documentElement.dir='rtl';render();if(!S.profileComplete)setTimeout(openOnboarding,250);else generate();if('serviceWorker' in navigator){try{await navigator.serviceWorker.register('sw.js')}catch(e){}}await initAuth()});
